import { Schema, InferSchemaType, HydratedDocument } from "mongoose";
import { RESERVATION_STATUSES } from "./enums";
import { defineModel } from "./_define";

const reservationSchema = new Schema(
  {
    businessId: { type: Schema.Types.ObjectId, ref: "Business", required: true, index: true },
    callId: { type: Schema.Types.ObjectId, ref: "Call", index: true },
    /** Generated by StayDesk's booking system, never by the AI. Unique per business. */
    confirmationCode: { type: String, required: true },
    guestName: { type: String, required: true, trim: true },
    guestPhone: { type: String, default: "" },
    guestEmail: { type: String, default: "" },
    roomTypeId: { type: Schema.Types.ObjectId, ref: "RoomType", required: true },
    roomTypeName: { type: String, required: true },
    /** Local calendar dates, "YYYY-MM-DD" (check-out day is not a night stayed). */
    checkIn: { type: String, required: true },
    checkOut: { type: String, required: true },
    nights: { type: Number, required: true, min: 1 },
    guests: { type: Number, default: 1, min: 1 },
    nightlyRate: { type: Number, required: true },
    totalAmount: { type: Number, required: true },
    status: { type: String, enum: RESERVATION_STATUSES, default: "confirmed" },
    source: { type: String, enum: ["ai_call", "staff", "test"], default: "ai_call" },
    history: [{ _id: false, at: { type: Date, default: () => new Date() }, action: String, detail: String }],
    isDemo: { type: Boolean, default: false },
  },
  { timestamps: true },
);
reservationSchema.index({ businessId: 1, confirmationCode: 1 }, { unique: true });
reservationSchema.index({ businessId: 1, roomTypeId: 1, checkIn: 1, checkOut: 1 });

export type ReservationAttrs = InferSchemaType<typeof reservationSchema>;
export type ReservationDoc = HydratedDocument<ReservationAttrs>;
export const Reservation = defineModel("Reservation", reservationSchema);
